pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address funder, address caller, uint256 amount) public {
        vm.assume(funder != address(0) && caller != address(0));
        vm.assume(caller != address(this)); // owner is the test contract; exclude owner from caller domain
        vm.assume(funder != address(c));
        amount = bound(amount, 1, 1 ether);

        // fund the contract through its payable fallback
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool s, ) = address(c).call{value: amount}("");
        require(s, "fallback deposit failed");
        require(address(c).balance == amount, "deposit not held");

        uint256 balanceBefore = address(c).balance;

        // drive c through withdrawAll with a (possibly non-owner) caller
        vm.prank(caller);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // General rule: any withdrawAll call either reverts or drains the balance only for the owner;
        // a non-owner call must not both succeed and zero the balance.
        assertTrue(!ok || address(c).balance == balanceBefore);
    }
}

