        vm.assume(funder != address(0) && funder != address(c));
        vm.assume(caller != address(0) && caller != address(c));
        // owner of c is this test contract (msg.sender in setUp); the caller must be a NON-owner
        vm.assume(caller != address(this));
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the contract through its payable fallback
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool funded, ) = address(c).call{value: amount}("");
        vm.assume(funded);
        vm.assume(address(c).balance >= amount);
        uint256 balBefore = address(c).balance;

