        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for every admissible input, a non-owner's withdrawAll either reverts
        // or leaves the contract's balance untouched. The mutant lets the non-owner succeed
        // and drain the whole balance (ok == true with balance zeroed), breaking the rule.
        assertTrue(!ok || address(c).balance == balBefore, "non-owner must not drain the contract");
    }
